def lowestCommonAncestor(root: list, p: int, q: int) -> int:
    curr = 0
    while curr < len(root) and root[curr] is not None:
        val = root[curr]
        if p > val and q > val:
            curr = 2 * curr + 2
        elif p < val and q < val:
            curr = 2 * curr + 1
        else:
            return val
    return root[0]

